// Collect unique websites from the incoming rows (a sheet column or Google Maps results)
// and send them to the Contact Details Scraper in ONE run (cheaper and faster than one run per row).
const FIELDS = ['website', 'Website', 'WEBSITE', 'url', 'URL', 'Url', 'domain', 'Domain', 'DOMAIN'];

function hostOf(value) {
  let v = String(value || '').trim();
  if (!v) return null;
  if (v.includes('@') && !v.includes('://')) v = v.split('@').pop();
  if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
  try {
    const host = new URL(v).hostname.toLowerCase().replace(/^www\./, '');
    return host.includes('.') ? host : null;
  } catch (e) {
    return null;
  }
}

const seen = new Set();
const websites = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const raw = FIELDS.map((f) => row[f]).find((v) => v);
  const host = hostOf(raw);
  if (host && !seen.has(host)) {
    seen.add(host);
    websites.push(host);
  }
}

if (websites.length === 0) {
  throw new Error('No websites found. Make sure your rows have a "website", "url" or "domain" column.');
}

return [{ json: { websites, count: websites.length } }];

// Join each Google Maps place with the contacts found on its website (matched by domain).
function hostOf(value) {
  let v = String(value || '').trim();
  if (!v) return null;
  if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
  try {
    return new URL(v).hostname.toLowerCase().replace(/^www\./, '');
  } catch (e) {
    return null;
  }
}

const contactsByDomain = {};
for (const item of $input.all()) {
  const c = item.json || {};
  if (c.domain) contactsByDomain[c.domain] = c;
}

const rows = [];
const done = new Set();
for (const item of $('Find businesses on Google Maps').all()) {
  const p = item.json || {};
  const domain = hostOf(p.website);
  const key = p.placeId || domain || p.title;
  if (!key || done.has(key)) continue; // skip duplicate places
  done.add(key);
  const c = (domain && contactsByDomain[domain]) || {};
  rows.push({
    json: {
      business_name: p.title || '',
      category: p.categoryName || '',
      address: p.address || '',
      city: p.city || '',
      state: p.state || '',
      postal_code: p.postalCode || '',
      maps_phone: p.phone || '',
      rating: p.totalScore ?? '',
      reviews: p.reviewsCount ?? '',
      website: domain || '',
      email: c.primaryEmail || '',
      all_emails: c.allEmails || '',
      website_phone: c.primaryPhone || '',
      facebook: c.facebook || '',
      instagram: c.instagram || '',
      linkedin: c.linkedin || '',
      contact_page: c.contactPageUrl || '',
      contact_form: c.contactFormUrl || '',
      email_provider: c.mailboxProvider || '',
      google_maps_url: p.url || '',
      contacts_found: Boolean(c.contactsFound),
    },
  });
}

return rows;
